begin;
do $$
declare queue_count int; owner_actor uuid; client uuid:=gen_random_uuid(); stranger uuid:=gen_random_uuid(); salon_slug text; services jsonb; staff jsonb; v_draft jsonb; v_content jsonb; options jsonb; chosen jsonb; booked jsonb; retry jsonb; request_id uuid:=gen_random_uuid(); blocked boolean; when_date date:=(now() at time zone 'Asia/Kolkata')::date+5;
begin
 select w.owner_id,w.slug,a.draft,w.content into owner_actor,salon_slug,v_draft,v_content from public.studioflow_websites w join public.studioflow_accounts a on a.user_id=w.owner_id limit 1;
 if owner_actor is null then raise exception 'No published salon for contract tests';end if;
 insert into auth.users(id,aud,role,email,raw_app_meta_data,raw_user_meta_data) values(client,'authenticated','authenticated',client::text||'@android-qa.invalid','{}','{"full_name":"Android QA"}'),(stranger,'authenticated','authenticated',stranger::text||'@android-qa.invalid','{}','{}');
 services:='[{"id":"android-qa-a","name":"QA Haircut","description":"QA","category":"Hair","price":249.01,"durationMinutes":30,"icon":"spa"},{"id":"android-qa-b","name":"QA Treatment","description":"QA","category":"Hair","price":150,"durationMinutes":45,"icon":"spa"}]';
 staff:='[{"id":"android-qa-staff","name":"QA Specialist","role":"Stylist","avatarUrl":"","status":"Available","schedule":[],"assignedServices":["android-qa-a","android-qa-b"]}]';
 perform set_config('request.jwt.claim.sub',owner_actor::text,true);
 update public.studioflow_accounts set draft=jsonb_set(jsonb_set(jsonb_set(v_draft,'{services}',services),'{stylists}',staff),'{extras,bookingLeadHours}','0') where user_id=owner_actor;
 update public.studioflow_websites set content=jsonb_set(jsonb_set(v_content,'{services}',services),'{stylists}',staff) where owner_id=owner_actor;
 perform set_config('request.jwt.claim.sub',client::text,true);execute 'set local role authenticated';
 perform public.studioflow_android_profile();perform public.studioflow_android_save_profile('Android QA','9876543210');
 if (public.studioflow_android_profile()->>'full_name')<>'Android QA' then raise exception 'Profile did not persist';end if;
 perform public.studioflow_android_favorite(salon_slug);
 if not exists(select 1 from public.studioflow_android_favorites where customer_id=client) then raise exception 'Favorite missing';end if;
 options:=public.studioflow_android_slots(salon_slug,'["android-qa-a","android-qa-b"]',when_date,'android-qa-staff');chosen:=options->0;
 if chosen is null then raise exception 'Expected available 75-minute appointment';end if;
 booked:=public.studioflow_android_book(salon_slug,'["android-qa-a","android-qa-b"]',when_date,chosen->>'time',chosen->>'stylistId','Android QA','9876543210','QA instruction',request_id);
 if (booked->'payload'->>'servicePrice')::numeric<>399.01 or (booked->'payload'->>'durationMinutes')::int<>75 or booked->>'status'<>'pending' then raise exception 'Booking snapshot mismatch';end if;
 blocked:=false;begin perform public.studioflow_book(salon_slug,jsonb_build_object('serviceId','android-qa-a','stylistId',chosen->>'stylistId','date',when_date,'time',chosen->>'time','clientName','Customer Wiring QA','clientPhone','9876543210'));exception when others then blocked:=true;end;
 if not blocked then raise exception 'Website allowed overlap with customer-app booking';end if;
 perform set_config('request.jwt.claim.sub',owner_actor::text,true);
 if not exists(select 1 from public.studioflow_bookings where id=(booked->>'id')::uuid) then raise exception 'App booking missing from owner website workspace';end if;
 perform set_config('request.jwt.claim.sub',client::text,true);
 retry:=public.studioflow_android_book(salon_slug,'["android-qa-a","android-qa-b"]',when_date,chosen->>'time',chosen->>'stylistId','Android QA','9876543210','QA instruction',request_id);
 if booked->>'id'<>retry->>'id' then raise exception 'Duplicate booking on retry';end if;
 blocked:=false;begin perform public.studioflow_android_book(salon_slug,'["android-qa-a","android-qa-b"]',when_date,chosen->>'time',chosen->>'stylistId','Android QA','9876543210','QA instruction',gen_random_uuid());exception when others then blocked:=true;end;
 if not blocked then raise exception 'Overlapping booking accepted';end if;
 blocked:=false;begin perform public.studioflow_android_slots(salon_slug,'["android-qa-a","android-qa-a"]',when_date,'any');exception when others then blocked:=true;end;
 if not blocked then raise exception 'Duplicate services accepted';end if;
 blocked:=false;begin perform public.studioflow_android_review(salon_slug,'Android QA',5,'Premature review should fail');exception when others then blocked:=true;end;
 if not blocked then raise exception 'Uncompleted visit review accepted';end if;
 perform set_config('request.jwt.claim.sub',stranger::text,true);
 if exists(select 1 from public.studioflow_android_profiles where customer_id=client) or exists(select 1 from public.studioflow_android_favorites where customer_id=client) or exists(select 1 from public.studioflow_bookings where id=(booked->>'id')::uuid) then raise exception 'Cross-customer read allowed';end if;
 blocked:=false;begin perform public.studioflow_update_booking((booked->>'id')::uuid,'cancelled');exception when others then blocked:=true;end;
 if not blocked then raise exception 'Cross-customer cancellation allowed';end if;
 execute 'set local role postgres';
 if not exists(select 1 from public.studioflow_android_push_queue where booking_id=(booked->>'id')::uuid) then raise exception 'Booking notification not queued';end if;
 insert into public.studioflow_customer_preferences(customer_id,notifications_enabled) values(client,false) on conflict(customer_id) do update set notifications_enabled=false;
 select count(*) into queue_count from public.studioflow_android_push_queue where booking_id=(booked->>'id')::uuid;
 update public.studioflow_bookings set status='confirmed',payload=payload||jsonb_build_object('status','confirmed','paymentStatus','paid_deposit','amountPaid',99.76) where id=(booked->>'id')::uuid;
 if (select count(*) from public.studioflow_android_push_queue where booking_id=(booked->>'id')::uuid)<>queue_count then raise exception 'Notification opt-out was ignored';end if;
 update public.studioflow_customer_preferences set notifications_enabled=true where customer_id=client;

 perform set_config('request.jwt.claim.sub',client::text,true);execute 'set local role authenticated';
 retry:=public.studioflow_android_reschedule((booked->>'id')::uuid,when_date+1,chosen->>'time',chosen->>'stylistId');
 if retry->>'status'<>'confirmed' or (retry->'payload'->>'amountPaid')::numeric<>99.76 or (retry->'payload'->>'date')::date<>when_date+1 then raise exception 'Reschedule did not preserve payment';end if;
 blocked:=false;begin perform public.studioflow_android_reschedule((booked->>'id')::uuid,when_date+1,'23:59',chosen->>'stylistId');exception when others then blocked:=true;end;
 if not blocked then raise exception 'Invalid reschedule accepted';end if;
 if not exists(select 1 from public.studioflow_bookings where id=(booked->>'id')::uuid and status='confirmed' and (payload->>'date')::date=when_date+1) then raise exception 'Failed move lost original appointment';end if;
 retry:=public.studioflow_book(salon_slug,jsonb_build_object('serviceId','android-qa-a','stylistId',chosen->>'stylistId','date',when_date,'time',chosen->>'time','clientName','Customer Wiring QA','clientPhone','9876543210'));
 if not exists(select 1 from public.studioflow_bookings where id=(retry->>'id')::uuid and customer_id=client) then raise exception 'Website booking missing from customer app records';end if;
 blocked:=false;begin perform public.studioflow_android_book(salon_slug,'["android-qa-a","android-qa-b"]',when_date,chosen->>'time',chosen->>'stylistId','Customer Wiring QA','9876543210','Cross-channel overlap test',gen_random_uuid());exception when others then blocked:=true;end;
 if not blocked then raise exception 'Customer app allowed overlap with website booking';end if;
 execute 'set local role postgres';
 if exists(select 1 from pg_class where relname like 'studioflow_android_%' and relkind='r' and not relrowsecurity) then raise exception 'RLS missing';end if;
end $$;
rollback;
select 'PASS: website-to-app and app-to-owner booking visibility, cross-channel overlap prevention, profiles, favorites, 75-minute multi-service reservation, server price snapshot, idempotency, overlaps, duplicate services, verified-visit review guard, customer isolation, cancellation guard, payment-preserving reschedule, atomic move rollback, push queue opt-out enforced, RLS; all fixture data rolled back' as verification;

